commit;

select
    310 as expected_projects,
    count(*) as seeded_project_rows,
    count(*) filter (where status <> 'draft' or price is not null or not catalog_visible) as rows_outside_public_unpriced_draft_state
from public.service_projects
where source_document like 'Inventory ID: %';
